for name in ['Normal','Title','Heading 1','Heading 2']:
 st=d.styles[name];st.font.name='Inter' if name=='Normal' else 'Jost';st.font.color.rgb=RGBColor.from_string(INK);st.font.size=Pt(9.5 if name=='Normal' else 17 if name=='Title' else 12)

